-- FixFlow Phase 2 — 0001_init
-- Creates all tables, composite uniques, composite FKs, and CHECKs.
-- RLS is enabled in 0002_rls_policies.
CREATE TYPE "MembershipRole" AS ENUM ('owner', 'admin', 'manager', 'technician', 'cashier');
CREATE TYPE "RepairStatus" AS ENUM ('received', 'diagnosing', 'awaiting_approval', 'awaiting_parts', 'in_repair', 'ready', 'delivered', 'cancelled');
CREATE TYPE "SubscriptionStatus" AS ENUM ('trial', 'active', 'past_due', 'suspended', 'cancelled', 'expired');

CREATE TABLE "tenants" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "branches" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("tenantId", "id"), FOREIGN KEY ("tenantId") REFERENCES "tenants"("id"));
CREATE TABLE "users" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "memberships" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "role" "MembershipRole" NOT NULL, "branchIds" TEXT[] NOT NULL DEFAULT '{}', "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("userId", "tenantId"), FOREIGN KEY ("userId") REFERENCES "users"("id"), FOREIGN KEY ("tenantId") REFERENCES "tenants"("id"));
CREATE TABLE "roles" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, UNIQUE ("tenantId", "name"));
CREATE TABLE "permissions" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL UNIQUE);
CREATE TABLE "role_permissions" ("roleId" TEXT NOT NULL, "permissionId" TEXT NOT NULL, PRIMARY KEY ("roleId", "permissionId"), FOREIGN KEY ("roleId") REFERENCES "roles"("id"), FOREIGN KEY ("permissionId") REFERENCES "permissions"("id"));
CREATE TABLE "customers" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "phone" TEXT, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("tenantId", "id"), FOREIGN KEY ("tenantId") REFERENCES "tenants"("id"));
CREATE TABLE "devices" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "customerId" TEXT NOT NULL, "brand" TEXT NOT NULL, "model" TEXT NOT NULL, "serial" TEXT, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("tenantId", "id"), FOREIGN KEY ("tenantId", "customerId") REFERENCES "customers"("tenantId", "id"));
CREATE TABLE "repair_orders" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "branchId" TEXT NOT NULL, "customerId" TEXT NOT NULL, "deviceId" TEXT NOT NULL, "status" "RepairStatus" NOT NULL DEFAULT 'received', "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("tenantId", "id"), FOREIGN KEY ("tenantId", "branchId") REFERENCES "branches"("tenantId", "id"), FOREIGN KEY ("tenantId", "customerId") REFERENCES "customers"("tenantId", "id"), FOREIGN KEY ("tenantId", "deviceId") REFERENCES "devices"("tenantId", "id"));
CREATE TABLE "repair_events" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "orderId" TEXT NOT NULL, "actorId" TEXT NOT NULL, "fromStatus" "RepairStatus", "toStatus" "RepairStatus" NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY ("tenantId", "orderId") REFERENCES "repair_orders"("tenantId", "id"));
CREATE TABLE "repair_approvals" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "orderId" TEXT NOT NULL, "type" TEXT NOT NULL, "amount" DECIMAL(19,4), "status" TEXT NOT NULL DEFAULT 'pending', "approverId" TEXT, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK ("amount" IS NULL OR "amount" >= 0), FOREIGN KEY ("tenantId", "orderId") REFERENCES "repair_orders"("tenantId", "id"));
CREATE TABLE "parts" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "sku" TEXT NOT NULL, "name" TEXT NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("tenantId", "sku"), UNIQUE ("tenantId", "id"), FOREIGN KEY ("tenantId") REFERENCES "tenants"("id"));
CREATE TABLE "branch_stock" ("tenantId" TEXT NOT NULL, "branchId" TEXT NOT NULL, "partId" TEXT NOT NULL, "qtyOnHand" INTEGER NOT NULL DEFAULT 0, "reservedQty" INTEGER NOT NULL DEFAULT 0, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY ("tenantId", "branchId", "partId"), CHECK ("qtyOnHand" >= 0), CHECK ("reservedQty" >= 0), FOREIGN KEY ("tenantId", "branchId") REFERENCES "branches"("tenantId", "id"), FOREIGN KEY ("tenantId", "partId") REFERENCES "parts"("tenantId", "id"));
CREATE TABLE "stock_movements" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "branchId" TEXT NOT NULL, "partId" TEXT NOT NULL, "qty" INTEGER NOT NULL, "reason" TEXT NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY ("tenantId", "branchId", "partId") REFERENCES "branch_stock"("tenantId", "branchId", "partId"));
CREATE TABLE "suppliers" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("tenantId", "id"), FOREIGN KEY ("tenantId") REFERENCES "tenants"("id"));
CREATE TABLE "purchase_orders" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "branchId" TEXT NOT NULL, "supplierId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'draft', "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("tenantId", "id"), FOREIGN KEY ("tenantId", "supplierId") REFERENCES "suppliers"("tenantId", "id"));
CREATE TABLE "purchase_order_lines" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "purchaseOrderId" TEXT NOT NULL, "partId" TEXT NOT NULL, "qty" INTEGER NOT NULL CHECK ("qty" > 0), "unitPrice" DECIMAL(19,4) NOT NULL CHECK ("unitPrice" >= 0), FOREIGN KEY ("tenantId", "purchaseOrderId") REFERENCES "purchase_orders"("tenantId", "id"));
CREATE TABLE "invoices" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "branchId" TEXT NOT NULL, "orderId" TEXT NOT NULL, "currency" TEXT NOT NULL, "total" DECIMAL(19,4) NOT NULL CHECK ("total" >= 0), "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("tenantId", "id"), FOREIGN KEY ("tenantId", "branchId") REFERENCES "branches"("tenantId", "id"), FOREIGN KEY ("tenantId", "orderId") REFERENCES "repair_orders"("tenantId", "id"));
CREATE TABLE "payments" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "invoiceId" TEXT NOT NULL, "method" TEXT NOT NULL, "amount" DECIMAL(19,4) NOT NULL CHECK ("amount" >= 0), "idempotencyKey" TEXT NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("tenantId", "idempotencyKey"), UNIQUE ("tenantId", "id"), FOREIGN KEY ("tenantId", "invoiceId") REFERENCES "invoices"("tenantId", "id"));
CREATE TABLE "refunds" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "invoiceId" TEXT NOT NULL, "paymentId" TEXT, "amount" DECIMAL(19,4) NOT NULL CHECK ("amount" >= 0), "reason" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("tenantId", "id"), FOREIGN KEY ("tenantId", "invoiceId") REFERENCES "invoices"("tenantId", "id"), FOREIGN KEY ("tenantId", "paymentId") REFERENCES "payments"("tenantId", "id"));
CREATE TABLE "ledger_entries" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "invoiceId" TEXT NOT NULL, "refType" TEXT NOT NULL, "refId" TEXT NOT NULL, "amount" DECIMAL(19,4) NOT NULL, "direction" TEXT NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY ("tenantId", "invoiceId") REFERENCES "invoices"("tenantId", "id"));
CREATE TABLE "plans" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL);
CREATE TABLE "plan_versions" ("id" TEXT PRIMARY KEY, "planId" TEXT NOT NULL, "version" INTEGER NOT NULL, UNIQUE ("planId", "version"), FOREIGN KEY ("planId") REFERENCES "plans"("id"));
CREATE TABLE "subscriptions" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "planVersionId" TEXT NOT NULL, "status" "SubscriptionStatus" NOT NULL DEFAULT 'trial', "currentPeriodEnd" TIMESTAMPTZ, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("tenantId", "id"), FOREIGN KEY ("tenantId") REFERENCES "tenants"("id"), FOREIGN KEY ("planVersionId") REFERENCES "plan_versions"("id"));
CREATE TABLE "entitlements" ("id" TEXT PRIMARY KEY, "planVersionId" TEXT NOT NULL, "feature" TEXT NOT NULL, "limitValue" INTEGER, UNIQUE ("planVersionId", "feature"), FOREIGN KEY ("planVersionId") REFERENCES "plan_versions"("id"));
CREATE TABLE "webhook_events" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "provider" TEXT NOT NULL, "eventId" TEXT NOT NULL, "payloadHash" TEXT NOT NULL, "processedAt" TIMESTAMPTZ, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("tenantId", "provider", "eventId"));
CREATE TABLE "tenant_branding" ("tenantId" TEXT PRIMARY KEY, "logoKey" TEXT, "colors" JSONB, "domain" TEXT, FOREIGN KEY ("tenantId") REFERENCES "tenants"("id"));
CREATE TABLE "resellers" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL);
CREATE TABLE "reseller_tenants" ("resellerId" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "terms" JSONB, PRIMARY KEY ("resellerId", "tenantId"), FOREIGN KEY ("resellerId") REFERENCES "resellers"("id"));
CREATE TABLE "audit_log" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "actorId" TEXT NOT NULL, "action" TEXT NOT NULL, "entity" TEXT NOT NULL, "entityId" TEXT NOT NULL, "before" JSONB, "after" JSONB, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY ("tenantId") REFERENCES "tenants"("id"));

CREATE INDEX "customers_tenant_created_idx" ON "customers" ("tenantId", "createdAt" DESC, "id" DESC);
CREATE INDEX "repair_orders_tenant_created_idx" ON "repair_orders" ("tenantId", "createdAt" DESC, "id" DESC);
CREATE INDEX "repair_orders_tenant_branch_created_idx" ON "repair_orders" ("tenantId", "branchId", "createdAt" DESC, "id" DESC);
CREATE INDEX "invoices_tenant_created_idx" ON "invoices" ("tenantId", "createdAt" DESC, "id" DESC);
CREATE INDEX "parts_tenant_created_idx" ON "parts" ("tenantId", "createdAt" DESC, "id" DESC);
CREATE INDEX "audit_log_tenant_created_idx" ON "audit_log" ("tenantId", "createdAt" DESC, "id" DESC);
